fun send(message: ByteArray): Int {
    val seq = nextSeq
    val data = Frame(Frame.Kind.DATA, seq, message).encode()
    for (attempt in 1..maxAttempts) {
        if (attempt > 1) retransmissions++                       // silence last time: send it again
        socket.send(DatagramPacket(data, data.size, peer))      // may vanish silently
        socket.soTimeout = timeout.toMillis().toInt()
        try {
            while (true) {                                       // skip stale ACKs
                val p = DatagramPacket(ByteArray(65_535), 65_535)
                socket.receive(p)
                val f = Frame.decode(p.data, p.length) ?: continue
                if (f.kind == Frame.Kind.ACK && f.seq == seq) {
                    nextSeq = seq + 1
                    return attempt
                }
            }
        } catch (e: SocketTimeoutException) {
            // no ACK in time: go round again
        }
    }
    throw DeliveryFailedException("no ACK for seq $seq")
}

